const defaultOptionsFor = (product: ShopProduct): Pick<ShopProduct, "options" | "customTextField"> => {
  if (product.id === "encyclopédie-des-rêves-et-des-cauchemars") return {
    options: [{ id: "dedicace", label: "Dédicace", choices: [
      { id: "sans", label: "Sans dédicace" },
      { id: "simple", label: "Dédicace simple" },
      { id: "dessinee", label: "Dédicace dessinée", priceDelta: 5 },
    ] }],
    customTextField: { label: "Dédicace pour :", placeholder: "Prénom ou message à inscrire (facultatif)", maxLength: 500 },
  };
  if (product.id === "sous-verres") return {
    options: [
      { id: "quantite", label: "Lot ou à l’unité", choices: [{ id: "unite", label: "À l’unité" }, { id: "lot-4", label: "Lot de 4", priceDelta: 10 }] },
      { id: "modele", label: "Modèle", choices: [
        { id: "santa-muerte", label: "Santa Muerte" }, { id: "emma", label: "Emma Jane Austen" },
        { id: "tea-books", label: "Tea & Books" }, { id: "bonne-biere", label: "La Bonne Bière" },
      ] },
    ],
    customTextField: { label: "Lot de 4 modèles différents :", placeholder: "Précisez ici la composition souhaitée (facultatif)", maxLength: 500 },
  };
  if (product.category === "Affiches" && product.from && product.price > 0) return {
    options: [{ id: "format", label: "Format", choices: [
      { id: "a4", label: "Format A4 (210 × 297 mm)" },
      { id: "a3", label: "Format A3 (297 × 420 mm)", priceDelta: 6 },
      { id: "a4-cadre", label: "A4 encadré — cadre noir 30 × 40 cm", priceDelta: 18 },
    ] }],
  };
  return {};
};

const productThumbnail = (image: string) => image.startsWith("/shop/") && !image.startsWith("/shop/thumbs/")
  ? image.replace("/shop/", "/shop/thumbs/")
  : image;
const productDetail = (image: string) => image.startsWith("/shop/") && !image.startsWith("/shop/detail/")
  ? image.replace("/shop/", "/shop/detail/")
  : image;

export const shopProducts: ShopProduct[] = baseShopProducts.map((product) => ({
  ...product,
  image: productThumbnail(product.image),
  images: product.images.map(productDetail),
  ...defaultOptionsFor(product),
}));
